Blockly.MJ_EMOJI_CHAR_ = function(codes) {
  var parts = codes.split(' ');
  var out = '';
  for (var i = 0; i < parts.length; i++) {
    var cp = parseInt(parts[i], 16);
    if (cp < 0x10000) {
      out += String.fromCharCode(cp);
    } else {
      cp -= 0x10000;
      out += String.fromCharCode(0xD800 + (cp >> 10), 0xDC00 + (cp & 0x3FF));
    }
  }
  return out;
};

for (var mjGroupIndex = 0; mjGroupIndex < Blockly.MJ_EMOJI_GROUPS.length;
     mjGroupIndex++) {
  (function(group, index) {
    var options = [];
    for (var i = 0; i < group.items.length; i++) {
      options.push([Blockly.MJ_EMOJI_CHAR_(group.items[i]), group.items[i]]);
    }
    Blockly.Blocks['majordomo_emoji_' + (index + 1)] = {
      init: function() {
        var label = Blockly.Msg['MAJORDOMO_EMOJI_G' + (index + 1)] || group.name;
        this.setColour(160);
        this.appendDummyInput()
            .appendField(label)
            .appendField(new Blockly.FieldDropdown(options.slice()), 'EMOJI');
        this.setOutput(true, 'String');
        this.setTooltip(Blockly.Msg.MAJORDOMO_EMOJI_TOOLTIP || '');
      }
    };
  })(Blockly.MJ_EMOJI_GROUPS[mjGroupIndex], mjGroupIndex);
}
